// Original teaching diagram, informed by the Kala KA-C's published dimensions.
export const INSTRUMENT_PARTS = [
  {id:'headstock',name:'Headstock & tuners',hint:'Make tiny turns, then listen.',description:'Four tuning machines hold the strings. Each peg adjusts one string’s tension and pitch. Follow a string to its tuner before turning anything.'},
  {id:'nut',name:'Nut',hint:'The starting line for an open string.',description:'The pale strip between headstock and fingerboard guides all four strings. An open string vibrates from the nut to the saddle.'},
  {id:'frets',name:'Fingerboard & frets',hint:'Fingertip just behind the wire.',description:'Metal fret wires divide the fingerboard into pitches. Put your finger in the space just behind a wire, without pressing directly on it. The spaces get smaller toward the body.'},
  {id:'strings',name:'Four strings',hint:'g · C · E · A',description:'In standard high-g tuning, the strings are g4, C4, E4 and A4. The g string is closest to your face while holding a right-handed ukulele. A is closest to the floor.'},
  {id:'body',name:'Body & sound hole',hint:'Let the wood do the singing.',description:'The figure-eight body has a smaller upper bout, a narrow waist and a wider lower bout. The wooden soundboard and hollow body help the strings’ vibrations become sound.'},
  {id:'bridge',name:'Bridge & saddle',hint:'Where the strings meet the body.',description:'The dark bridge anchors the strings. The pale saddle supports them at their other vibrating end. For a gentle strum, brush the strings near where the neck meets the body.'}
];
export function instrumentSVG(part='body',lefty=false){
 const active=id=>id===part?'#cf7445':'#998260';
 const strings=lefty?[3,2,1,0]:[0,1,2,3];
 const nut=110,scale=370,fretY=n=>nut+scale*(1-2**(-n/12));
 const fretLines=Array.from({length:18},(_,i)=>{const y=fretY(i+1),w=17+(y-nut)*.024;return `<path d="M${180-w} ${y}H${180+w}" stroke="#c3b395" stroke-width="1.25"/>`;}).join('');
 const markers=[5,7,10,12,15].map(n=>{const y=(fretY(n)+fretY(n-1))/2;return n===12?`<circle cx="173" cy="${y}" r="2"/><circle cx="187" cy="${y}" r="2"/>`:`<circle cx="180" cy="${y}" r="2.1"/>`;}).join('');
 const points={headstock:[217,56],nut:[206,110],frets:[207,218],strings:[200,298],body:[260,438],bridge:[224,481]};
 const [hx,hy]=points[part]||points.body;
 return `<svg class="instrument-svg" viewBox="0 0 360 610" role="img" aria-label="Illustrated concert ukulele with four tuners, four strings, eighteen frets, a figure-eight body, sound hole, nut and saddle. Selected part: ${INSTRUMENT_PARTS.find(p=>p.id===part)?.name||'body'}"><defs><linearGradient id="wood" x1="0" x2="1"><stop stop-color="#a86435"/><stop offset=".44" stop-color="#d9a46b"/><stop offset=".64" stop-color="#bd8045"/><stop offset="1" stop-color="#b1733d"/></linearGradient><pattern id="woodgrain" width="19" height="120" patternUnits="userSpaceOnUse"><path d="M5 0Q11 30 5 60T5 120M14 0Q8 35 14 70T14 120" fill="none" stroke="#754923" stroke-opacity=".18" stroke-width=".8"/></pattern><linearGradient id="metal"><stop stop-color="#b8bcb0"/><stop offset=".45" stop-color="#f2f1df"/><stop offset="1" stop-color="#818a7a"/></linearGradient></defs><ellipse cx="183" cy="589" rx="82" ry="9" fill="#584028" opacity=".08"/><path d="M157 322C133 312 104 328 104 358C104 384 132 396 125 420C119 440 80 452 80 497C80 552 121 580 180 580C239 580 280 552 280 497C280 452 241 440 235 420C228 396 256 384 256 358C256 328 227 312 203 322Z" fill="url(#wood)" stroke="#8c5c35" stroke-width="3"/><path d="M157 322C133 312 104 328 104 358C104 384 132 396 125 420C119 440 80 452 80 497C80 552 121 580 180 580C239 580 280 552 280 497C280 452 241 440 235 420C228 396 256 384 256 358C256 328 227 312 203 322Z" fill="url(#woodgrain)"/><path d="M157 325C134 317 109 331 109 358C109 382 137 395 130 421C123 444 85 456 85 497C85 549 124 575 180 575C236 575 275 549 275 497C275 456 237 444 230 421C223 395 251 382 251 358C251 331 226 317 203 325" fill="none" stroke="#ead7b0" stroke-width="2.5"/><circle cx="180" cy="391" r="34" fill="#66482f" stroke="#e8ca98" stroke-width="3"/><circle cx="180" cy="391" r="29.5" fill="#2f3025"/><circle cx="180" cy="391" r="36.5" fill="none" stroke="#735534" stroke-width="1"/><path d="M163 110H197L203 351H157Z" fill="#483728" stroke="#352b22" stroke-width="2"/>${fretLines}<g fill="#dfd2b5">${markers}</g><path d="M163 108L153 89L147 18Q180 5 213 18L207 89L197 108Z" fill="url(#wood)" stroke="#956337" stroke-width="2"/><path d="M153 22Q180 13 207 22" fill="none" stroke="#e3bc86" stroke-width="1"/><g fill="url(#metal)" stroke="#919887" stroke-width="1">${[41,76].map(y=>`<path d="M146 ${y}h-9M214 ${y}h9"/><ellipse cx="132" cy="${y}" rx="7" ry="9"/><ellipse cx="228" cy="${y}" rx="7" ry="9"/><circle cx="159" cy="${y}" r="6"/><circle cx="201" cy="${y}" r="6"/>`).join('')}</g><rect x="162" y="108" width="36" height="5" rx="1" fill="#f0dfb9"/><rect x="140" y="472" width="80" height="24" rx="3" fill="#5f3d27" stroke="#80502e" stroke-width="2"/><rect x="149" y="477" width="62" height="4" rx="1" fill="#efdfbc"/><g fill="none" stroke-linecap="round">${strings.map((s,i)=>{const nx=167+i*8.667,bx=161+i*12.667;return `<path d="M${i<2?159:201} ${i%2?41:76}L${nx} 110L${bx} 482v9" stroke="${part==='strings'?['#ad684d','#c29831','#6d9063','#8073a5'][s]:'#f6e5be'}" stroke-width="${part==='strings'?2.7:[1.05,1.55,1.3,.95][s]}"/>`;}).join('')}</g><circle cx="${hx}" cy="${hy}" r="12" fill="${active(part)}" fill-opacity=".18"/><circle cx="${hx}" cy="${hy}" r="5" fill="${active(part)}" stroke="#fffaf0" stroke-width="2"/><path d="M${hx+13} ${hy}h24" stroke="${active(part)}" stroke-width="1.5"/><g fill="#8a795e" font-family="DM Sans, sans-serif" font-size="9" letter-spacing="1.2"><text x="180" y="607" text-anchor="middle">CONCERT UKULELE · FRONT VIEW</text></g></svg>`;
}
export function sleeveSVG(number=0){
 const colors=[['#c77954','#f1d6ad'],['#3d6458','#cee0b4'],['#777399','#e1d9ef'],['#a2884b','#f3e4b9'],['#5c7e87','#d9e5df'],['#9b6660','#ebd4cb']];
 const [ink,paper]=colors[number%6],motif=number%3;
 return `<svg viewBox="0 0 90 100" aria-hidden="true" focusable="false"><rect width="90" height="100" fill="${paper}"/><path d="M0 76Q24 51 46 75T90 72V100H0Z" fill="${ink}" opacity=".17"/>${motif===0?`<g fill="none" stroke="${ink}" stroke-width="1.1">${[12,20,28,36].map(r=>`<circle cx="46" cy="43" r="${r}"/>`).join('')}</g><circle cx="46" cy="43" r="4" fill="${ink}"/>`:motif===1?`<circle cx="61" cy="29" r="14" fill="${ink}" opacity=".65"/><g fill="none" stroke="${ink}" stroke-width="1.5">${[47,55,63,71].map(y=>`<path d="M0 ${y}Q22 ${y-15} 45 ${y}T90 ${y}"/>`).join('')}</g>`:`<path d="M-5 68L28 23 51 54 70 30 100 77Z" fill="${ink}" opacity=".6"/><path d="M0 80L36 44 59 68 80 50 100 81Z" fill="${ink}" opacity=".6"/><circle cx="64" cy="18" r="6" fill="${ink}" opacity=".5"/>`}<path d="M10 87h20M10 91h12" stroke="${ink}" opacity=".7"/><text x="79" y="91" text-anchor="end" fill="${ink}" font-family="serif" font-size="9">${String(number||1).padStart(2,'0')}</text></svg>`;
}
